from __future__ import annotations
import copy
STATES={'launcher': ['default', 'recent', 'empty', 'command_palette', 'new_folder', 'choose_kernel'], 'notebook': ['editing', 'executed', 'running', 'error', 'split', 'restart_kernel'], 'file_browser': ['list', 'selected', 'searching', 'empty', 'rename', 'delete_files'], 'console': ['ready', 'history', 'running', 'error', 'kernel_disconnected', 'change_kernel'], 'editor': ['python', 'markdown_preview', 'json', 'split', 'find_replace', 'unsaved_close'], 'csv_viewer': ['data', 'delimiter', 'missing_values', 'scrolled', 'empty', 'options'], 'terminal': ['shell', 'output', 'split', 'process_running', 'disconnected', 'shutdown_terminal'], 'running_sessions': ['active', 'expanded', 'idle', 'filtered', 'shutdown_kernel', 'shutdown_all'], 'settings': ['notebook', 'editor', 'terminal', 'shortcuts', 'json', 'reset_settings'], 'extensions': ['discover', 'installed', 'details', 'disabled', 'install_confirm', 'uninstall_confirm']}
POPUPS={'shutdown_terminal', 'reset_settings', 'install_confirm', 'options', 'delete_files', 'change_kernel', 'uninstall_confirm', 'shutdown_all', 'shutdown_kernel', 'new_folder', 'rename', 'unsaved_close', 'choose_kernel', 'restart_kernel'}
TITLES={'launcher': 'Launcher', 'notebook': 'analysis.ipynb', 'file_browser': 'Files', 'console': 'Console 1', 'editor': 'utils.py', 'csv_viewer': 'observations.csv', 'terminal': 'Terminal 1', 'running_sessions': 'Running Sessions', 'settings': 'Settings', 'extensions': 'Extension Manager'}
CODE='import pandas as pd\nfrom pathlib import Path\n\nDATA_DIR = Path("data")\n\ndef load_observations(filename="observations.csv"):\n    frame = pd.read_csv(DATA_DIR / filename)\n    return frame.dropna(subset=["temperature"])\n\ndef summarize(frame):\n    return frame.groupby("station")["temperature"].mean()\n\nif __name__ == "__main__":\n    observations = load_observations()\n    print(summarize(observations))\n'
def generate_data(page,sample_index=0,assets_dir=None):
 if page not in STATES:raise ValueError(page)
 return {'page':page,'state':STATES[page][0],'title':TITLES[page],'popup_visible':False,'sample_index':sample_index,'code':CODE,'files':[{'name':n,'icon':i,'size':s,'modified':m} for n,i,s,m in [('data','folder','—','Today 09:10'),('notebooks','folder','—','Today 09:12'),('analysis.ipynb','book','18 KB','Today 09:41'),('observations.csv','table_chart','4 KB','Today 09:30'),('utils.py','code','2 KB','Yesterday'),('README.md','description','1 KB','Yesterday'),('environment.yml','data_object','1 KB','2 days ago')]], 'commands':['Notebook: Run All Cells','Notebook: Restart Kernel','File: New Notebook','File: Save All','View: Show Left Sidebar','Terminal: Create New','Settings: Change Theme'],'extensions':[{'name':n,'publisher':p,'description':d,'installed':i<2} for i,(n,p,d) in enumerate([('@demo/notebook-tools','Demo Tools','Notebook cell utilities and navigation'),('@demo/table-inspector','Demo Data','Inspect tabular output and schemas'),('@demo/theme-pack','Demo Themes','Readable light and dark editor themes'),('@demo/markdown-tools','Demo Docs','Markdown authoring helpers')])], 'rows':[{'id':i+1,'station':['River','Hill','Park'][i%3],'temperature':round(18.4+(i%7)*0.8,1),'humidity':52+i%14,'date':f'2026-06-{(i%28)+1:02d}'} for i in range(30)],'sessions':[{'name':n,'kind':k,'icon':i,'status':s} for n,k,i,s in [('analysis.ipynb','Python 3 (ipykernel)','book','Idle'),('experiments.ipynb','Python 3 (ipykernel)','book','Busy'),('Console 1','Python 3 (ipykernel)','code','Idle'),('Terminal 1','Terminal','terminal','Running')]]}
def apply_state(base,state):
 if state not in STATES[base['page']]:raise ValueError(state)
 d=copy.deepcopy(base);d['state']=state;d['popup_visible']=state in POPUPS
 if base['page']=='editor' and state in ['markdown_preview','json']:d['title']='README.md' if state=='markdown_preview' else 'config.json'
 if state=='empty':d['files']=[];d['rows']=[]
 if state=='searching':d['files']=[f for f in d['files'] if f['name'].endswith('.ipynb')]
 if state=='idle':d['sessions']=[]
 if state=='filtered':d['sessions']=[s for s in d['sessions'] if s['kind']=='Terminal']
 if state=='installed':d['extensions']=[e for e in d['extensions'] if e['installed']]
 if state=='scrolled':d['rows']=d['rows'][15:]
 if state=='missing_values':d['rows'][2]['temperature']=None;d['rows'][4]['humidity']=None
 return d
